// Variable pour stocker l'ID final
let spreadsheetId = null;

try {
  // 1. On vérifie si le nœud de création a tourné
  // ATTENTION: Ici il s'appelle "Create spreadsheet" (sans le 1)
  const createNode = $('Create spreadsheet');

  if (createNode.first()) {
    spreadsheetId = createNode.first().json.spreadsheetId;
  }
} catch (error) {
  // Si le nœud n'a pas été exécuté, on ignore
}

// 2. Si on n'a pas trouvé d'ID, on le prend du Webhook 'anglais'
if (!spreadsheetId) {
  const webhookData = $('anglais').first().json.body;
  // On récupère le bon champ "activeFileId"
  spreadsheetId = webhookData.activeFileId || webhookData.spreadsheetId;
}

// On renvoie l'ID propre pour la suite
return[
  {
    json: {
      finalSpreadsheetId: spreadsheetId
    }
  }
];

// On récupère la réponse de l'IA (Correction du nom du nœud)
// Attention: Vérifiez si la réponse est dans content.parts[0].text (Gemini API directe) 
// ou output (LangChain). Vu votre config LangChain, ça devrait être 'text' ou 'output'.
// Je mets une sécurité.
const aiNode = $('Message a model6').item.json;
const aiResponse = aiNode.content?.parts?.[0]?.text || aiNode.text || aiNode.output || "Pas de réponse";

// On récupère le spreadsheetId depuis le nœud 'Session_id'
const spreadsheetId = $('Session_id').item.json.finalSpreadsheetId;

// On récupère les infos du webhook original
const sessionId = $('anglais').item.json.body.sessionId;
const subject = $('anglais').item.json.body.subject;

return [
  {
    json: {
      response: aiResponse,
      spreadsheetId: spreadsheetId,
      sessionId: sessionId,
      subject: subject,
      timestamp: new Date().toISOString()
    }
  }
];

